import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        source_ip TEXT
    )''')
    db.commit()
    db.close()

@app.before_request
def log_request():
    """Audit logging for compliance - logs all API access"""
    try:
        db = get_db()
        db.execute(
            "INSERT INTO audit_log (action, source_ip) VALUES (?, ?)",
            (request.path, request.remote_addr)
        )
        db.commit()
    except Exception:
        pass

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Build query with validated field name and user-supplied value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID"""
    db = get_db()
    user = db.execute(
        'SELECT id, username, email, role FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v1/users', methods=['POST'])
def create_user():
    """Create a new user"""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'username and email required'}), 400

    try:
        db = get_db()
        db.execute(
            'INSERT INTO users (username, email) VALUES (?, ?)',
            (data['username'], data['email'])
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
